<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_role('admin');
$quizId = filter_var($_REQUEST['quiz_id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0;
$quizStatement = db()->prepare('SELECT q.id, q.title, l.title AS lesson_title, c.title AS course_title FROM quizzes q INNER JOIN lessons l ON l.id = q.lesson_id INNER JOIN courses c ON c.id = l.course_id WHERE q.id = :id'); $quizStatement->execute(['id' => $quizId]); $quiz = $quizStatement->fetch(); if (!$quiz) { set_flash('danger', 'Quiz not found.'); redirect('admin/quizzes.php'); }
$errors = []; $editQuestion = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['csrf_token'] ?? null)) $errors[] = 'Your session token expired.';
    $action = post_string('action'); $questionId = filter_var($_POST['question_id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0; $text = post_string('question_text'); $points = filter_var($_POST['points'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => 1000]]); $sortOrder = filter_var($_POST['sort_order'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => 9999]]); $optionInputs = is_array($_POST['options'] ?? null) ? $_POST['options'] : []; $correct = filter_var($_POST['correct_option'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 0, 'max_range' => 9]]);
    if ($action === 'delete' && !$errors) { $statement = db()->prepare('DELETE FROM questions WHERE id = :id AND quiz_id = :quiz_id'); $statement->execute(['id' => $questionId, 'quiz_id' => $quizId]); set_flash('success', 'Question deleted.'); redirect('admin/questions.php?quiz_id=' . $quizId); }
    if ($action !== 'delete') { if ($text === '') $errors[] = 'Enter the question text.'; if ($points === false || $sortOrder === false) $errors[] = 'Points and order must be valid numbers.'; $cleanOptions = []; foreach ($optionInputs as $option) { $option = trim((string)$option); if ($option !== '') $cleanOptions[] = $option; } if (count($cleanOptions) < 2) $errors[] = 'Add at least two answer options.'; if ($correct === false || !array_key_exists((int)$correct, $cleanOptions)) $errors[] = 'Select one correct answer.'; if ($action === 'update' && !$questionId) $errors[] = 'Invalid question.'; if (!$errors) { db()->beginTransaction(); try { if ($action === 'update') { $statement = db()->prepare('UPDATE questions SET question_text = :text, points = :points, sort_order = :sort_order WHERE id = :id AND quiz_id = :quiz_id'); $statement->execute(['text' => $text, 'points' => $points, 'sort_order' => $sortOrder, 'id' => $questionId, 'quiz_id' => $quizId]); $delete = db()->prepare('DELETE FROM question_options WHERE question_id = :question_id'); $delete->execute(['question_id' => $questionId]); } else { $statement = db()->prepare('INSERT INTO questions (quiz_id, question_text, points, sort_order) VALUES (:quiz_id, :text, :points, :sort_order)'); $statement->execute(['quiz_id' => $quizId, 'text' => $text, 'points' => $points, 'sort_order' => $sortOrder]); $questionId = (int)db()->lastInsertId(); } $optionStatement = db()->prepare('INSERT INTO question_options (question_id, option_text, is_correct) VALUES (:question_id, :option_text, :is_correct)'); foreach ($cleanOptions as $index => $option) $optionStatement->execute(['question_id' => $questionId, 'option_text' => $option, 'is_correct' => $index === (int)$correct ? 1 : 0]); db()->commit(); set_flash('success', 'Question saved.'); redirect('admin/questions.php?quiz_id=' . $quizId); } catch (Throwable $exception) { if (db()->inTransaction()) db()->rollBack(); $errors[] = 'The question could not be saved.'; } } $editQuestion = ['id' => $questionId, 'question_text' => $text, 'points' => $points, 'sort_order' => $sortOrder, 'options' => $cleanOptions, 'correct' => $correct]; }
}
if (!$editQuestion && isset($_GET['edit'])) { $id = filter_var($_GET['edit'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if ($id) { $statement = db()->prepare('SELECT id, question_text, points, sort_order FROM questions WHERE id = :id AND quiz_id = :quiz_id'); $statement->execute(['id' => $id, 'quiz_id' => $quizId]); $editQuestion = $statement->fetch() ?: null; if ($editQuestion) { $options = db()->prepare('SELECT option_text, is_correct FROM question_options WHERE question_id = :question_id ORDER BY id'); $options->execute(['question_id' => $id]); $editQuestion['options'] = []; $editQuestion['correct'] = 0; foreach ($options->fetchAll() as $index => $option) { $editQuestion['options'][] = $option['option_text']; if ($option['is_correct']) $editQuestion['correct'] = $index; } } } }
$questionStatement = db()->prepare('SELECT id, question_text, points, sort_order FROM questions WHERE quiz_id = :quiz_id ORDER BY sort_order, id'); $questionStatement->execute(['quiz_id' => $quizId]); $questions = $questionStatement->fetchAll();
$pageTitle = 'Manage questions'; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 fw-bold">Manage questions</h1><p class="text-secondary mb-0"><?= e($quiz['course_title'] . ' / ' . $quiz['lesson_title'] . ' / ' . $quiz['title']) ?></p></div><a class="btn btn-outline-primary" href="<?= e(app_url('admin/quizzes.php')) ?>">Back to quizzes</a></div><?php if ($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><div class="row g-4 align-items-start"><div class="col-lg-5"><div class="card"><div class="card-body p-4"><h2 class="h5"><?= $editQuestion ? 'Edit question' : 'Add question' ?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $editQuestion ? 'update' : 'create' ?>"><?php if ($editQuestion): ?><input type="hidden" name="question_id" value="<?= (int)$editQuestion['id'] ?>"><?php endif; ?><div class="mb-3"><label class="form-label">Question</label><textarea class="form-control" name="question_text" rows="4" required><?= e($editQuestion['question_text'] ?? '') ?></textarea></div><div class="row g-3 mb-3"><div class="col-6"><label class="form-label">Points</label><input class="form-control" name="points" type="number" min="1" max="1000" value="<?= e((string)($editQuestion['points'] ?? 10)) ?>" required></div><div class="col-6"><label class="form-label">Order</label><input class="form-control" name="sort_order" type="number" min="1" value="<?= e((string)($editQuestion['sort_order'] ?? 1)) ?>" required></div></div><?php for ($index = 0; $index < 4; $index++): ?><div class="input-group mb-2"><div class="input-group-text"><input type="radio" name="correct_option" value="<?= $index ?>" <?= ((int)($editQuestion['correct'] ?? 0) === $index) ? 'checked' : '' ?> aria-label="Correct option"></div><input class="form-control" name="options[]" value="<?= e($editQuestion['options'][$index] ?? '') ?>" placeholder="Option <?= $index + 1 ?>"></div><?php endfor; ?><button class="btn btn-primary mt-2" type="submit">Save question</button><?php if ($editQuestion): ?><a class="btn btn-link mt-2" href="<?= e(app_url('admin/questions.php?quiz_id=' . $quizId)) ?>">Cancel</a><?php endif; ?></form></div></div></div><div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5">Questions</h2><?php if (!$questions): ?><p class="text-secondary">No questions added.</p><?php endif; ?><?php foreach ($questions as $question): ?><div class="border-bottom py-3"><div class="d-flex justify-content-between"><strong><?= (int)$question['sort_order'] ?>. <?= e($question['question_text']) ?></strong><span><?= (int)$question['points'] ?> pts</span></div><a class="btn btn-sm btn-outline-secondary mt-2" href="<?= e(app_url('admin/questions.php?quiz_id=' . $quizId . '&edit=' . $question['id'])) ?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete this question?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="btn btn-sm btn-outline-danger mt-2">Delete</button></form></div><?php endforeach; ?></div></div></div></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
